INSERT INTO `task_comments` (`id`, `task_id`, `user_id`, `content`, `created_at`) VALUES
(1,9,5,'@[Nguyễn Đức Thắng](usr-9) nhớ khóa bản ghi khi kiểm tra khung giờ để tránh hai bệnh nhân đặt trùng nhau.','2026-10-16 10:15:00'),
(2,9,9,'Mình đã thêm ràng buộc duy nhất theo bác sĩ và giờ bắt đầu, đang chạy thử với 50 yêu cầu song song.','2026-10-16 12:45:00'),
(3,9,3,'Ổn rồi, nhớ ghi kết quả thử tải vào tài liệu để làm bằng chứng khi nghiệm thu.','2026-10-16 15:15:00'),
(4,17,13,'@[Trịnh Thu Hà](usr-10) màn hình chọn giờ bị lệch một dòng trên máy màn hình nhỏ, bạn xem giúp nhé.','2026-10-30 10:15:00'),
(5,17,10,'Mình đã nhận, chiều nay sẽ sửa xong.','2026-10-30 12:45:00'),
(6,18,3,'@[Nguyễn Đức Thắng](usr-9) lỗi múi giờ đang ảnh hưởng nhiều bệnh nhân, bạn cập nhật tiến độ giúp mình trước 3 giờ chiều nay.','2026-10-30 10:15:00'),
(7,18,9,'Nguyên nhân là máy chủ lưu giờ UTC còn ứng dụng đọc theo giờ máy. Chiều nay mình đưa bản vá.','2026-10-30 12:45:00'),
(8,34,8,'@[Hoàng Mạnh Cường](usr-7) đề xuất là trưởng nhóm duyệt trước, phòng nhân sự duyệt cuối. Bạn xem sơ đồ đính kèm giúp mình.','2026-10-23 10:15:00'),
(9,34,7,'Mình đồng ý, nhưng cần thêm nhánh tự động chuyển cấp khi người duyệt đang nghỉ phép.','2026-10-23 12:45:00'),
(10,34,4,'Chốt theo hướng của @[Hoàng Mạnh Cường](usr-7) nhé. @[Nguyễn Thị Thảo](usr-8) cập nhật lại tài liệu trong hôm nay.','2026-10-23 15:15:00'),
(11,41,4,'@[Trần Quốc Bảo](usr-11) phòng nhân sự cần báo cáo này trước kỳ chốt công cuối tháng, bạn ưu tiên giúp mình.','2026-11-03 10:15:00'),
(12,41,11,'Phần tổng hợp đã xong, mình đang tối ưu truy vấn vì dữ liệu cả năm chạy hơi chậm.','2026-11-03 12:45:00'),
(13,63,6,'@[Nguyễn Đức Thắng](usr-9) tối qua thử 200 đơn đồng thời vẫn thấy tồn kho âm ở 3 sản phẩm.','2026-11-05 10:15:00'),
(14,63,9,'Mình xác nhận lỗi này, đang chuyển sang khóa theo từng sản phẩm. Dự kiến trễ thêm 2 ngày.','2026-11-05 12:45:00'),
(15,63,3,'Mình ghi nhận rủi ro này vào báo cáo tuần. @[Trần Quốc Bảo](usr-11) hỗ trợ @[Nguyễn Đức Thắng](usr-9) phần kiểm thử tải nhé.','2026-11-05 15:15:00'),
(16,63,11,'Mình nhận, sẽ viết bộ thử tải ngay hôm nay.','2026-11-05 17:45:00'),
(17,64,3,'@[Nguyễn Đức Thắng](usr-9) ngân hàng vừa gửi lại tài khoản thử nghiệm, bạn lấy trong thư mục chung rồi tích hợp tiếp.','2026-11-05 10:15:00'),
(18,64,9,'Đã nhận, mình chạy thử thành công giao dịch đầu tiên.','2026-11-05 12:45:00'),
(19,66,8,'Phần này đang chờ phòng kế toán xác nhận quy tắc hoàn tiền một phần, mình sẽ cập nhật ngay khi có phản hồi.','2026-11-03 10:15:00'),
(20,79,8,'Khách hàng đã ký duyệt tài liệu phiên bản 1.2, tệp đính kèm bên dưới.','2026-08-25 10:15:00'),
(21,79,4,'Cảm ơn @[Nguyễn Thị Thảo](usr-8). Từ giờ mọi thay đổi yêu cầu phải qua quy trình thay đổi phạm vi.','2026-08-25 12:45:00'),
(22,90,4,'@[Nguyễn Đức Thắng](usr-9) khách hàng hỏi về tiến độ kiểm kê theo lô, bạn cho mình ngày chốt dự kiến nhé.','2026-10-27 10:15:00'),
(23,90,9,'Dự kiến 20/11 xong phần kiểm kê theo lô, phần theo vị trí kệ sẽ làm sau.','2026-10-27 12:45:00'),
(24,90,5,'Phần vị trí kệ thuộc giai đoạn sau, @[Trần Minh Quân](usr-4) ghi nhận vào danh sách thay đổi giúp mình.','2026-10-27 15:15:00'),
(25,92,11,'Máy quét dòng mới trả về mã có ký tự xuống dòng, mình đã thêm bước làm sạch dữ liệu đầu vào.','2026-11-03 10:15:00'),
(26,92,6,'@[Trần Quốc Bảo](usr-11) cảm ơn bạn, mình sẽ bổ sung ca kiểm thử cho trường hợp này.','2026-11-03 12:45:00'),
(27,93,6,'@[Nguyễn Đức Thắng](usr-9) còn 4 lỗi mức cao ở module nhập kho, nhờ bạn xử lý trước thứ Hai.','2026-10-27 10:15:00'),
(28,93,9,'Mình nhận, sẽ gửi bản sửa trong ngày mai.','2026-10-27 12:45:00');
