(1,1,2,'2026-09-28',4,'Rà soát tài liệu','Đọc lại toàn bộ tài liệu, sửa các chỗ mâu thuẫn giữa các mục và thống nhất thuật ngữ.',55,'APPROVED',3,'2026-09-29 10:15:00',NULL,'2026-09-28 17:30:00','2026-09-29 10:15:00'),
