(3,2,7,'2026-09-28',6,'Hoàn thiện bản thiết kế','Chuẩn hóa màu sắc, cỡ chữ, khoảng cách và dựng thêm trạng thái rỗng, trạng thái lỗi.',55,'APPROVED',3,'2026-09-29 10:15:00',NULL,'2026-09-28 17:30:00','2026-09-29 10:15:00'),
(4,2,7,'2026-10-09',5,'Thử trên nhiều kích thước','Kiểm tra lại thiết kế trên màn hình nhỏ và lớn, sửa những chỗ bị tràn hoặc quá chật.',100,'APPROVED',3,'2026-10-10 10:15:00',NULL,'2026-10-09 17:30:00','2026-10-10 10:15:00'),
(5,3,3,'2026-09-28',4,'Xử lý lỗi phát sinh','Tìm nguyên nhân và sửa các lỗi phát hiện khi chạy thử trên môi trường kiểm thử.',50,'APPROVED',3,'2026-09-29 10:15:00',NULL,'2026-09-28 17:30:00','2026-09-29 10:15:00'),
(6,3,3,'2026-10-09',4,'Cài đặt xử lý chính','Viết phần xử lý chính, kiểm tra dữ liệu đầu vào và trả mã lỗi rõ ràng khi dữ liệu sai.',100,'APPROVED',3,'2026-10-10 10:15:00',NULL,'2026-10-09 17:30:00','2026-10-10 10:15:00'),
(7,4,3,'2026-09-29',6,'Xử lý lỗi phát sinh','Tìm nguyên nhân và sửa các lỗi phát hiện khi chạy thử trên môi trường kiểm thử.',50,'APPROVED',3,'2026-09-30 10:15:00',NULL,'2026-09-29 17:30:00','2026-09-30 10:15:00'),
(8,4,3,'2026-10-09',6,'Sửa theo review','Chỉnh lại code theo nhận xét của người review, tách bớt hàm quá dài và đặt lại tên cho dễ đọc.',100,'APPROVED',3,'2026-10-10 10:15:00',NULL,'2026-10-09 17:30:00','2026-10-10 10:15:00'),
