(10,5,4,'2026-10-09',4,'Xử lý trạng thái','Thêm trạng thái đang tải, danh sách rỗng và thông báo lỗi để người dùng không bị trống màn hình.',100,'APPROVED',3,'2026-10-10 10:15:00',NULL,'2026-10-09 17:30:00','2026-10-10 10:15:00'),
(11,6,6,'2026-09-28',3,'Soạn kịch bản kiểm thử','Viết các ca kiểm thử cho luồng chính và các trường hợp lỗi, chuẩn bị sẵn dữ liệu mẫu.',50,'APPROVED',3,'2026-09-29 10:15:00',NULL,'2026-09-28 17:30:00','2026-09-29 10:15:00'),
(12,6,6,'2026-10-09',3,'Báo lỗi và theo dõi','Tạo báo cáo lỗi kèm các bước tái hiện, trao đổi với đội lập trình về mức độ ưu tiên.',100,'APPROVED',3,'2026-10-10 10:15:00',NULL,'2026-10-09 17:30:00','2026-10-10 10:15:00'),
(13,7,3,'2026-10-14',6,'Tối ưu truy vấn','Đo thời gian truy vấn, thêm chỉ mục còn thiếu và bỏ bớt truy vấn lặp, thời gian giảm rõ rệt.',55,'APPROVED',3,'2026-10-15 10:15:00',NULL,'2026-10-14 17:30:00','2026-10-15 10:15:00'),
