SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;
SET UNIQUE_CHECKS = 0;
SET SQL_MODE = 'NO_AUTO_VALUE_ON_ZERO';


-- RBAC-BEGIN: roles, permissions, role_permissions (giữ nguyên, không chứa dữ liệu nghiệp vụ)
LOCK TABLES `roles` WRITE;
UNLOCK TABLES;

LOCK TABLES `permissions` WRITE;
UNLOCK TABLES;

LOCK TABLES `role_permissions` WRITE;
UNLOCK TABLES;
-- RBAC-END


SET UNIQUE_CHECKS = 1;
SET FOREIGN_KEY_CHECKS = 1;
